function createGrpcServer(source) {
  const server = http2.createServer();
  server.on("stream", (stream, headers) => {
    const path = headers[":path"];
    const chunks = [];
    stream.on("data", (chunk) => chunks.push(chunk));
    stream.on("error", () => undefined);
    stream.on("end", () => {
